root=Path.cwd();out=root/'output/aa-comparisons-2026-10-27';game=root/'run/aa-comparisons-20261027';deliver=out/'deliverables';raw=deliver/'originals';split=deliver/'split-view';pair=deliver/'full-scene-pairs'
