base=Image.open(game/'screenshots/compare-off-000.png').convert('RGB');end=Image.open(game/'screenshots/compare-off-final-000.png').convert('RGB');assert ImageChops.difference(base,end).getbbox() is None
base.save(raw/'00-off.png')
